from pydantic import BaseModel
from typing import List, Optional, Dict, Any
def Info(**kwargs): pass  # placeholder for import
class BaseMessageDataType(BaseModel):
    data: Any
    type: str
class RubyRisksCustomStrategy:
    def __init__(self, model: BaseModel):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = None
    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)
    def receive_message(self, message: Info) -> Info:
        # Unpack the incoming game state
        total_rubies, current_turn, feedback, boxes = message.message[0].data
        # Compute rubies and boxes remaining
        used = sum(feedback)
        remaining_rubies = total_rubies - used
        remaining_boxes = boxes - current_turn + 1
        # Request the floor of the average per box, at least 1 if any remain
        if remaining_boxes > 0 and remaining_rubies > 0:
            rubies_requested = remaining_rubies // remaining_boxes
            if rubies_requested < 1:
                rubies_requested = 1
        else:
            rubies_requested = 0
        # Package our decision
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=rubies_requested, type='custom')]
        )

